// Sources/Models/TarotCard.swift
import Foundation

public enum ElementType: String, Codable, Sendable, CaseIterable {
    case fire = "FIRE"
    case water = "WATER"
    case earth = "EARTH"
    case air = "AIR"
    case spirit = "SPIRIT"
    
    public var platonicSolid: String {
        switch self {
        case .fire: return "TETRAHEDRON"
        case .earth: return "HEXAHEDRON"
        case .air: return "OCTAHEDRON"
        case .water: return "ICOSAHEDRON"
        case .spirit: return "DODECAHEDRON"
        }
    }
    
    public var isMasculineActive: Bool {
        self == .fire || self == .air
    }
    
    public var isFemininePassive: Bool {
        self == .water || self == .earth
    }
}

public struct TarotCardDescriptor: Identifiable, Codable, Sendable, Hashable {
    public var id: String { name.uppercased() }
    public let name: String
    public let element: ElementType
    public let meaning: String
    public let jungianConcept: String
    public let reflectionPrompt: String
    
    public init(name: String, element: ElementType, meaning: String, jungianConcept: String, reflectionPrompt: String) {
        self.name = name
        self.element = element
        self.meaning = meaning
        self.jungianConcept = jungianConcept
        self.reflectionPrompt = reflectionPrompt
    }
}

