    public static let map: [String: TarotCardDescriptor] = {
        var dict: [String: TarotCardDescriptor] = [:]
        for card in cards {
            dict[card.name.uppercased()] = card
        }
        return dict
    }()
    
    public static func getCard(named name: String) -> TarotCardDescriptor? {
        map[name.uppercased()]
    }
